def can_divide_multiset(A, B, C):
    total_sum = A * 1 + B * 2 + C * 3
    if total_sum % 2 != 0:
        return 'NO'
    target_sum = total_sum // 2
    # Check if we can partition the multiset into two subsets with equal sum
    # We can use a dynamic programming approach to check this
    dp = [False] * (target_sum + 1)
    dp[0] = True
    for i in range(A):
        for j in range(target_sum, 0, -1):
            if j >= 1:
                dp[j] |= dp[j - 1]
    for i in range(B):
        for j in range(target_sum, 0, -1):
            if j >= 2:
                dp[j] |= dp[j - 2]
    for i in range(C):
        for j in range(target_sum, 0, -1):
            if j >= 3:
                dp[j] |= dp[j - 3]
    return 'YES' if dp[target_sum] else 'NO'

